import { Meta, StoryObj } from "@storybook/react";
import { expect, fn, userEvent, waitFor, within } from "storybook/test";
import { useState, useEffect } from "react";
import { Lightbox, LightboxItem } from "./light-box";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { ContentContainer } from "@/core/components/primitives/content-container/content-container";

const meta = {
  title: "Primitives/Lightbox",
  component: Lightbox,
  parameters: {
    layout: "centered",
    chromatic: { delay: 1000 },
    docs: {
      // The lightbox renders in the modal portal and covers the viewport, so an inline docs preview
      // lets it escape the small preview box and cover the docs page. Render the preview in an
      // iframe tall enough to show the open viewer instead.
      story: { inline: false, height: "600px" },
      description: {
        component:
          "Fullscreen media viewer for images and YouTube videos. Renders the items as a swipeable " +
          "carousel with arrow buttons, page indicator dots and keyboard navigation (arrow keys, " +
          "Escape to close). Navigation UI only shows when there is more than one item. The open " +
          "state is fully controlled via `isOpen`/`onClose`.",
      },
    },
  },
  argTypes: {
    isOpen: { control: "boolean" },
    initialIndex: { control: "number" },
  },
  args: { onClose: fn() },
} satisfies Meta<typeof Lightbox>;

export default meta;

type Story = StoryObj<typeof meta>;

// Sample images from picsum.photos
const sampleImages: Array<LightboxItem> = [
  { type: "image", url: "https://picsum.photos/seed/park1/800/600" },
  { type: "image", url: "https://picsum.photos/seed/park2/800/600" },
  { type: "image", url: "https://picsum.photos/seed/park3/800/600" },
  { type: "image", url: "https://picsum.photos/seed/park4/800/600" },
];

const singleImage: Array<LightboxItem> = [{ type: "image", url: "https://picsum.photos/seed/single/800/600" }];

const youtubeItems: Array<LightboxItem> = [
  {
    type: "youtube",
    url: "https://img.youtube.com/vi/dQw4w9WgXcQ/maxresdefault.jpg",
    youtubeUrl: "https://www.youtube.com/embed/dQw4w9WgXcQ",
  },
];

// Helper component for stories that need a trigger button with state management
const LightboxWithTrigger = ({
  items,
  initialIndex = 0,
  buttonLabel = "Open Lightbox",
  ...props
}: {
  items: Array<LightboxItem>;
  initialIndex?: number;
  buttonLabel?: string;
} & Omit<React.ComponentProps<typeof Lightbox>, "items" | "onClose">) => {
  const [isOpen, setIsOpen] = useState(props.isOpen);

  // Sync Storybook control changes to state
  useEffect(() => {
    setIsOpen(props.isOpen);
  }, [props.isOpen]);

  return (
    <ContentContainer>
      <PrimaryButton label={buttonLabel} onClick={() => setIsOpen(true)} />
      <Lightbox {...props} items={items} isOpen={isOpen} onClose={() => setIsOpen(false)} initialIndex={initialIndex} />
    </ContentContainer>
  );
};

export const Default: Story = {
  render: (args) => <LightboxWithTrigger {...args} items={sampleImages} buttonLabel="Open Image Gallery" />,
  args: {
    items: sampleImages,
    isOpen: true,
  },
};

