// Thumbnail gallery with controlled initial index
export const ThumbnailGallery: Story = {
  render: function StoryComponent() {
    const [isOpen, setIsOpen] = useState(false);
    const [clickedIndex, setClickedIndex] = useState(0);

    const thumbnails = sampleImages.map((item, index) => ({
      ...item,
      thumbnail: `https://picsum.photos/seed/park${index + 1}/200/150`,
    }));

    const handleThumbnailClick = (index: number) => {
      setClickedIndex(index);
      setIsOpen(true);
    };

    return (
      <>
        <div style={{ display: "flex", gap: "0.5rem", flexWrap: "wrap" }}>
          {thumbnails.map((item, index) => (
            <button
              key={index}
              onClick={() => handleThumbnailClick(index)}
              style={{
                padding: 0,
                border: "2px solid transparent",
                borderRadius: "4px",
                cursor: "pointer",
                overflow: "hidden",
              }}
            >
              <img
                src={item.thumbnail}
                alt={`Thumbnail ${index + 1}`}
                style={{ display: "block", width: "100px", height: "75px", objectFit: "cover" }}
              />
            </button>
          ))}
        </div>
        <Lightbox items={sampleImages} isOpen={isOpen} onClose={() => setIsOpen(false)} initialIndex={clickedIndex} />
      </>
    );
  },
  // Unused by the render - only here because the story type requires the component's required props.
  args: {
    items: sampleImages,
    isOpen: false,
  },
};

export const TestNavigation: Story = {
  render: (args) => <LightboxWithTrigger {...args} items={sampleImages} buttonLabel="Open Image Gallery" />,
  args: {
    items: sampleImages,
    isOpen: false,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByText("Open Image Gallery"));
    // The lightbox renders in the modal portal outside the story canvas, so query the whole document.
    const body = within(canvasElement.ownerDocument.body);
    const dots = await body.findAllByRole("button", { name: /^Visa/ });
    await expect(dots).toHaveLength(4);
    await expect(dots[0]).toHaveAttribute("data-active", "true");
    await userEvent.click(body.getByRole("button", { name: "Nästa" }));
    await expect(dots[1]).toHaveAttribute("data-active", "true");
    await userEvent.click(body.getByRole("button", { name: "Stäng" }));
    await waitFor(() => expect(body.queryByRole("button", { name: "Nästa" })).not.toBeInTheDocument());
  },
};
